#!/usr/bin/env python3
"""Fill HWPX template with patient intake data."""

import json
import re
import os
from xml.etree import ElementTree as ET

# Register namespaces to preserve them during serialization
namespaces = {
    'hp': 'http://www.hancom.co.kr/schema/2011/hp/',
}
for prefix, uri in namespaces.items():
    ET.register_namespace(prefix, uri)


def load_json(path):
    """Load JSON file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def compute_korean_age(birth_date_str, visit_date_str):
    """Compute Korean full-year age (만 나이).

    age = visit_year - birth_year
    if (visit_month, visit_day) < (birth_month, birth_day): age -= 1
    """
    birth_parts = birth_date_str.split('-')
    visit_parts = visit_date_str.split('-')

    birth_year = int(birth_parts[0])
    birth_month = int(birth_parts[1])
    birth_day = int(birth_parts[2])

    visit_year = int(visit_parts[0])
    visit_month = int(visit_parts[1])
    visit_day = int(visit_parts[2])

    age = visit_year - birth_year
    if (visit_month, visit_day) < (birth_month, birth_day):
        age -= 1

    return age


def normalize_phone(phone_str):
    """Normalize phone number to Korean mobile format.

    - Strip all non-digit characters
    - 10 digits: NNN-NNN-NNNN
    - 11 digits: NNN-NNNN-NNNN
    """
    digits = re.sub(r'\D', '', phone_str)

    if len(digits) == 10:
        return f"{digits[:3]}-{digits[3:6]}-{digits[6:]}"
    elif len(digits) == 11:
        return f"{digits[:3]}-{digits[3:7]}-{digits[7:]}"
    else:
        # Fallback: just return digits with hyphens every 3-4 chars
        return digits


def build_replacement_dict(data):
    """Build mapping from placeholders to final values."""
    # Compute age
    age = compute_korean_age(data['생년월일'], data['방문일'])

    # Format birth date with age
    birth_date_with_age = f"{data['생년월일']} ({age}세)"

    # Normalize phone
    normalized_phone = normalize_phone(data['회신전화'])

    return {
        '{{환자명}}': data['환자명'],
        '{{생년월일}}': birth_date_with_age,
        '{{방문일}}': data['방문일'],
        '{{진료팀}}': data['진료팀'],
        '{{회신전화}}': normalized_phone,
        '{{증상요약}}': data['증상요약'],
        '{{보험상태}}': data['보험상태'],
    }


def replace_in_text(text, replacements):
    """Replace all placeholders in text."""
    if text is None:
        return None
    result = text
    for placeholder, value in replacements.items():
        result = result.replace(placeholder, value)
    return result


def process_xml_file(filepath, replacements):
    """Process an XML file, replacing placeholders and removing lineSegArray."""
    tree = ET.parse(filepath)
    root = tree.getroot()

    # Track which paragraphs were modified
    modified_paras = set()

    # Walk all elements
    for elem in root.iter():
        # Check text content
        if elem.text and '{{' in elem.text:
            new_text = replace_in_text(elem.text, replacements)
            if new_text != elem.text:
                elem.text = new_text
                # Mark parent paragraph as modified
                parent = find_parent(root, elem)
                while parent is not None:
                    if parent.tag == '{http://www.hancom.co.kr/schema/2011/hp/}p':
                        modified_paras.add(parent)
                        break
                    parent = find_parent(root, parent)

        # Check tail content (text after element)
        if elem.tail and '{{' in elem.tail:
            new_tail = replace_in_text(elem.tail, replacements)
            if new_tail != elem.tail:
                elem.tail = new_tail
                # Mark parent paragraph as modified
                parent = find_parent(root, elem)
                while parent is not None:
                    if parent.tag == '{http://www.hancom.co.kr/schema/2011/hp/}p':
                        modified_paras.add(parent)
                        break
                    parent = find_parent(root, parent)

    # Remove lineSegArray from modified paragraphs
    hp_ns = '{http://www.hancom.co.kr/schema/2011/hp/}'
    for para in modified_paras:
        # Find all lineSegArray children
        to_remove = []
        for child in para:
            if child.tag == f'{hp_ns}linesegarray':
                to_remove.append(child)
        # Remove them
        for child in to_remove:
            para.remove(child)

    # Write back
    tree.write(filepath, encoding='utf-8', xml_declaration=True)


def find_parent(root, child_elem):
    """Find parent of an element."""
    for parent in root.iter():
        for child in parent:
            if child is child_elem:
                return parent
    return None


def main():
    # Load data
    data = load_json('/root/patient_intake.json')
    print(f"Loaded data: {data}")

    # Build replacements
    replacements = build_replacement_dict(data)
    print(f"Replacements: {replacements}")

    # Find all XML files with placeholders
    template_dir = '/tmp/hwpx_work/template'
    xml_files_with_placeholders = []

    for root_dir, dirs, files in os.walk(template_dir):
        for filename in files:
            if filename.endswith('.xml'):
                filepath = os.path.join(root_dir, filename)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if '{{' in content:
                            xml_files_with_placeholders.append(filepath)
                except Exception as e:
                    print(f"Warning: could not read {filepath}: {e}")

    print(f"XML files with placeholders: {xml_files_with_placeholders}")

    # Process each file
    for filepath in xml_files_with_placeholders:
        print(f"Processing: {filepath}")
        process_xml_file(filepath, replacements)

    # Verify no placeholders remain
    remaining = []
    for root_dir, dirs, files in os.walk(template_dir):
        for filename in files:
            if filename.endswith('.xml'):
                filepath = os.path.join(root_dir, filename)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                        matches = re.findall(r'\{\{.*?\}\}', content)
                        if matches:
                            remaining.append((filepath, matches))
                except Exception as e:
                    pass

    if remaining:
        print(f"ERROR: Placeholders still remain: {remaining}")
        raise RuntimeError(f"Placeholders still remain: {remaining}")
    else:
        print("SUCCESS: All placeholders replaced")


if __name__ == '__main__':
    main()

