import json
import re
import os
from xml.etree import ElementTree as ET

# Register namespaces to preserve them during serialization
namespaces = {
    'hp': 'http://www.hancom.co.kr/schema/2011/hp/',
}
for prefix, uri in namespaces.items():
    ET.register_namespace(prefix, uri)


def load_json(path):
    """Load JSON file."""
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)


def compute_korean_age(birth_date_str, visit_date_str):
    """Compute Korean full-year age (만 나이).

    age = visit_year - birth_year
    if (visit_month, visit_day) < (birth_month, birth_day): age -= 1
    """
    birth_parts = birth_date_str.split('-')
    visit_parts = visit_date_str.split('-')

    birth_year = int(birth_parts[0])
    birth_month = int(birth_parts[1])
    birth_day = int(birth_parts[2])

    visit_year = int(visit_parts[0])
    visit_month = int(visit_parts[1])
    visit_day = int(visit_parts[2])

    age = visit_year - birth_year
    if (visit_month, visit_day) < (birth_month, birth_day):
        age -= 1

    return age


def normalize_phone(phone_str):
    """Normalize phone number to Korean mobile format.

    - Strip all non-digit characters
    - 10 digits: NNN-NNN-NNNN
    - 11 digits: NNN-NNNN-NNNN
    """
    digits = re.sub(r'\D', '', phone_str)

    if len(digits) == 10:
        return f"{digits[:3]}-{digits[3:6]}-{digits[6:]}"
    elif len(digits) == 11:
        return f"{digits[:3]}-{digits[3:7]}-{digits[7:]}"
    else:
        # Fallback: just return digits with hyphens every 3-4 chars
        return digits


def build_replacement_dict(data):
    """Build mapping from placeholders to final values."""
    # Compute age
    age = compute_korean_age(data['생년월일'], data['방문일'])

    # Format birth date with age
    birth_date_with_age = f"{data['생년월일']} ({age}세)"

    # Normalize phone
    normalized_phone = normalize_phone(data['회신전화'])

    return {
        '{{환자명}}': data['환자명'],
        '{{생년월일}}': birth_date_with_age,
        '{{방문일}}': data['방문일'],
        '{{진료팀}}': data['진료팀'],
        '{{회신전화}}': normalized_phone,
        '{{증상요약}}': data['증상요약'],
        '{{보험상태}}': data['보험상태'],
    }


